<?php
use App\Accounts\DeviceAuth;
use App\Domain\{Access,Failure,RecorderHandoffs};
use App\Jobs\ArchiveLesson;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Route};
$classroomAdmin=function(Request $r,bool $sensitive=false):object{$u=Access::user($r->session()->get('uid'));Access::admin($u);if($sensitive)DeviceAuth::requireRecent($r);return $u;};
Route::get('/api/admin/lessons',function(Request $r)use($classroomAdmin){$classroomAdmin($r);$v=$r->validate(['course_id'=>'integer|min:1','search'=>'string|max:200','status'=>'in:ready,live,paused,ended','deleted'=>'boolean','page'=>'integer|min:1','sort'=>'in:name,created_at,duration','direction'=>'in:asc,desc']);$q=DB::table('lessons as l')->join('courses as c','c.id','=','l.course_id')->leftJoin('users as u','u.id','=','l.recorder_user_id')->select('l.*','c.name as course_name','u.name as recorder_name');if(!($v['deleted']??false))$q->whereNull('l.deleted_at');if(isset($v['course_id']))$q->where('l.course_id',$v['course_id']);if(isset($v['status']))$q->where('l.status',$v['status']);if(!empty($v['search']))$q->whereRaw('l.name ILIKE ?',['%'.addcslashes($v['search'],'%_\\').'%']);$sort=['name'=>'l.name','created_at'=>'l.created_at','duration'=>'l.media_samples'][$v['sort']??'created_at'];return ['lessons'=>$q->orderBy($sort,$v['direction']??'desc')->orderByDesc('l.id')->paginate(30)->through(fn($l)=>Access::publicLesson($l))];});
Route::post('/api/admin/lessons/{lesson}/end',function(Request $r,int $lesson)use($classroomAdmin){$u=$classroomAdmin($r,true);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');return DB::transaction(function()use($lesson,$u){$l=DB::table('lessons')->where('id',$lesson)->whereNull('deleted_at')->lockForUpdate()->first();if(!$l)throw new Failure('lesson_unavailable',404);if($l->status==='ended')return ['accepted'=>true];if(in_array($l->translation_status,['connecting','ready','finishing']))Access::event($lesson,'control.end',['actor_id'=>$u->id]);else{DB::table('lessons')->where('id',$lesson)->update(['status'=>'ended','ended_at'=>now(),'recorder_connection'=>null,'lease_until'=>null,'recorder_user_id'=>null]);(new RecorderHandoffs)->invalidate($lesson);Access::lessonEvent($lesson);ArchiveLesson::dispatch($lesson);}DeviceAuth::audit((int)$u->id,'lesson.end_requested',['lesson_id'=>$lesson]);return ['accepted'=>true];});});
Route::post('/api/admin/lessons/{lesson}/retry-archive',function(Request $r,int $lesson)use($classroomAdmin){$u=$classroomAdmin($r,true);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');$l=DB::table('lessons')->where('id',$lesson)->whereNull('deleted_at')->first();if(!$l)throw new Failure('lesson_unavailable',404);if($l->status!=='ended'||!in_array($l->archive_status,['failed','pending']))throw new Failure('invalid_state',409);ArchiveLesson::dispatch($lesson);DeviceAuth::audit((int)$u->id,'archive.retry_requested',['lesson_id'=>$lesson]);return ['queued'=>true];});
Route::delete('/api/admin/lessons/{lesson}',function(Request $r,int $lesson)use($classroomAdmin){$u=$classroomAdmin($r,true);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');return DB::transaction(function()use($u,$lesson){$l=DB::table('lessons')->where('id',$lesson)->lockForUpdate()->first();if(!$l)throw new Failure('lesson_unavailable',404);if($l->status!=='ended'||$l->archive_status==='processing')throw new Failure('lesson_must_end_before_delete',409);app(\App\Sharing\SharingService::class)->revoke($lesson,$u);DB::table('lessons')->where('id',$lesson)->update(['deleted_at'=>now(),'version'=>$l->version+1]);(new RecorderHandoffs)->invalidate($lesson);Access::lessonEvent($lesson);DeviceAuth::audit((int)$u->id,'lesson.soft_deleted',['lesson_id'=>$lesson]);return ['deleted'=>true];});});
Route::post('/api/admin/lessons/{lesson}/restore',function(Request $r,int $lesson)use($classroomAdmin){$u=$classroomAdmin($r,true);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');return DB::transaction(function()use($u,$lesson){$l=DB::table('lessons')->where('id',$lesson)->lockForUpdate()->first();if(!$l||$l->purge_status)throw new Failure('lesson_unavailable',404);DB::table('lessons')->where('id',$lesson)->update(['deleted_at'=>null,'version'=>$l->version+1]);Access::lessonEvent($lesson);DeviceAuth::audit((int)$u->id,'lesson.restored',['lesson_id'=>$lesson]);return ['restored'=>true];});});
Route::post('/api/admin/courses/{course}/restore',function(Request $r,int $course)use($classroomAdmin){$u=$classroomAdmin($r,true);if($r->input('confirmed')!==true)throw new Failure('confirmation_required');if(!DB::table('courses')->where('id',$course)->exists())throw new Failure('course_unavailable',404);DB::table('courses')->where('id',$course)->update(['deleted_at'=>null,'enabled'=>true,'updated_at'=>now()]);DeviceAuth::audit((int)$u->id,'course.restored',['course_id'=>$course]);return ['restored'=>true];});
